// UI_ASSETS is generated from the approved HTML/CSS files at build time.
// Authentication scripts and API endpoints in those pages remain unchanged.
const AUTH_STYLE_VERSION = '20261103-home-1';
const AUTH_UI_TYPES = {
  '/signin.html': 'text/html; charset=utf-8',
  '/signup.html': 'text/html; charset=utf-8',
  '/auth-ui.css': 'text/css; charset=utf-8',
  '/taktak.html': 'text/html; charset=utf-8',
  '/taktak-colors.css': 'text/css; charset=utf-8',
  '/site-ui.css': 'text/css; charset=utf-8',
  '/taktak-layout.css': 'text/css; charset=utf-8',
  '/taktak-layout.js': 'application/javascript; charset=utf-8',
  '/auth-guard.js': 'application/javascript; charset=utf-8',
  '/home-live-now.js': 'application/javascript; charset=utf-8',
  '/home-mini-tv.js': 'application/javascript; charset=utf-8',
  '/home-media-popups.js': 'application/javascript; charset=utf-8',
  '/platform-upgrades.js': 'application/javascript; charset=utf-8',
  '/taktak-feed.js': 'application/javascript; charset=utf-8'
};

function authPresentationResponse(path, request) {
  if (!Object.hasOwn(AUTH_UI_TYPES, path)) return null;
  if (!['GET', 'HEAD'].includes(request.method)) return new Response(null, {status: 405});
  return new Response(request.method === 'HEAD' ? null : UI_ASSETS[path], {
    headers: {
      'Content-Type': AUTH_UI_TYPES[path],
      'Cache-Control': 'no-store, max-age=0',
      'X-Content-Type-Options': 'nosniff',
      'X-Shenoo-Auth-Style': AUTH_STYLE_VERSION
    }
  });
}

// Shared presentation is injected only into application HTML; APIs and media pass through.
function sitePresentationResponse(response, path) {
  if (response.status !== 200 || !/text\/html/i.test(response.headers.get('Content-Type') || '')) return response;
  // Authentication already uses the approved stylesheet. Leave exported artwork intact.
  if (['/signin.html', '/signup.html'].includes(path) || path.startsWith('/canva-originals/')) return response;
  return new HTMLRewriter()
    .on('html', {element(el) {
      el.setAttribute('class', ((el.getAttribute('class') || '') + ' shenoo-ui-scope').trim());
      if (!el.getAttribute('data-theme')) el.setAttribute('data-theme', 'light');
    }})
    .on('head', {element(el) {el.append('<link rel="stylesheet" href="/site-ui.css?v=20261103-1" />', {html:true});}})
    .transform(response);
}

const BACKEND = "https://shino-mino-tak-tak.duckdns.org";
const FRONTEND = BACKEND;
const API_PREFIXES = ["/api/", "/socket.io", "/uploads/"];
function isBackendPath(path) { return API_PREFIXES.some((prefix) => path === prefix || path.startsWith(prefix)); }
function corsHeaders(request) {
 const origin=request.headers.get("Origin") || "*";
 return {
  "Access-Control-Allow-Origin": origin,
  "Access-Control-Allow-Methods": "GET,HEAD,POST,PUT,PATCH,DELETE,OPTIONS",
  "Access-Control-Allow-Headers": request.headers.get("Access-Control-Request-Headers") || "Authorization,Content-Type,Accept",
  "Access-Control-Max-Age": "600",
  "Vary": "Origin",
  "Cache-Control": "no-store"
 };
}
export default {
 async fetch(request) {
  const incoming=new URL(request.url);
  const presentation=authPresentationResponse(incoming.pathname,request);
  if(presentation) return sitePresentationResponse(presentation, incoming.pathname);
  const backend=isBackendPath(incoming.pathname);
  if(backend && request.method==="OPTIONS") return new Response(null,{status:204,headers:corsHeaders(request)});
  const target=new URL(incoming.pathname+incoming.search,backend?BACKEND:FRONTEND);
  const headers=new Headers(request.headers);
  headers.set("Origin",BACKEND);
  headers.delete("host");
  const init={method:request.method,headers,redirect:"manual"};
  if(request.method!=="GET"&&request.method!=="HEAD")init.body=request.body;
  let response;
  try{response=await fetch(new Request(target.toString(),init));}
  catch{return new Response(JSON.stringify({ok:false,error:"upstream_unavailable",message:"تعذر الاتصال بالخادم الأصلي"}),{status:502,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}});}
  if(response.status===101) return response;
  const location=response.headers.get("Location");
  if(location){
   const redirect=new URL(location,target);
   if(redirect.origin===BACKEND){
    const redirected=new Response(response.body,response);
    redirected.headers.set("Location",incoming.origin+redirect.pathname+redirect.search+redirect.hash);
    response=redirected;
   }
  }
  if(backend){
   const out=new Response(response.body,response);
   const ch=corsHeaders(request);
   for(const [k,v] of Object.entries(ch))out.headers.set(k,v);
   return out;
  }
  return sitePresentationResponse(response, incoming.pathname);
 }
};
